168				while (type != null && !Object.class.equals(type)) {
169					Method[] declaredMethods = getSorted(type, this::getDeclaredMethods, Method::getName);
170					Field[] declaredFields = getSorted(type, Class::getDeclaredFields, Field::getName);
171					addProperties(declaredMethods, declaredFields);
172					type = type.getSuperclass();
173				}
174			}
