176			private Method[] getDeclaredMethods(Class<?> type) {
177				Method[] methods = type.getDeclaredMethods();
178				Set<Method> result = new LinkedHashSet<>(methods.length);
179				for (Method method : methods) {
180					result.add(BridgeMethodResolver.findBridgedMethod(method));
