191			protected void addProperties(Method[] declaredMethods, Field[] declaredFields) {
192				@Nullable Method[] methods = new Method[declaredMethods.length];
193				for (int i = 0; i < declaredMethods.length; i++) {
194					methods[i] = isCandidate(declaredMethods[i]) ? declaredMethods[i] : null;
195				}
196				for (Method method : methods) {
197					addMethodIfPossible(method, "is", 0, BeanProperty::addGetter);
198				}
199				for (Method method : methods) {
200					addMethodIfPossible(method, "get", 0, BeanProperty::addGetter);
201				}
202				for (Method method : methods) {
203					addMethodIfPossible(method, "set", 1, BeanProperty::addSetter);
204				}
205				for (Field field : declaredFields) {
